import assert from "node:assert/strict";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { compareVersions, installBundledSkills, removeProjectBundledSkills } from "../src/bundled-skills.js";

const root = mkdtempSync(path.join(tmpdir(), "bundled-skills-test-"));
try {
  const codexHome = path.join(root, "codex");
  const projects = [path.join(root, "one"), path.join(root, "two")];
  const unrelated = path.join(root, "unrelated");
  for (const dir of [...projects, unrelated]) mkdirSync(dir);
  const source = path.join(root, "bundled-skills", "codex-telegram-bridge");
  mkdirSync(source, { recursive: true });
  writeFileSync(path.join(source, "SKILL.md"), "test\n");
  writeFileSync(path.join(source, "VERSION"), "1.0.0\n");
  const global = path.join(codexHome, "skills", "codex-telegram-bridge");
  mkdirSync(global, { recursive: true });
  writeFileSync(path.join(global, "SKILL.md"), "custom global contents\n");
  const run = () => installBundledSkills(root, { codexHome, projects });
  const first = run();
  assert.equal(first.filter(item => item.action === "installed").length, 2);
  const archive = first.find(item => item.action === "archived-global");
  assert.equal(readFileSync(path.join(archive.backup, "SKILL.md"), "utf8"), "custom global contents\n");
  assert.equal(existsSync(global), false);
  assert.equal(existsSync(path.join(unrelated, ".codex")), false);
  assert.equal(run()[0].action, "unchanged");
  writeFileSync(path.join(source, "VERSION"), "1.1.0\n");
  assert.equal(run()[0].action, "updated");
  const local = project => path.join(project, ".codex", "skills", "codex-telegram-bridge");
  writeFileSync(path.join(local(projects[0]), "SKILL.md"), "local edits\n");
  writeFileSync(path.join(local(projects[1]), "VERSION"), "9.0.0\n");
  writeFileSync(path.join(source, "VERSION"), "1.2.0\n");
  assert.equal(run()[0].action, "preserved-custom");
  assert.equal(run()[1].action, "unchanged");
  assert.equal(removeProjectBundledSkills(projects[0])[0].action, "preserved-custom");
  assert.equal(removeProjectBundledSkills(projects[1])[0].action, "preserved-custom");
  const clean = path.join(root, "clean"); mkdirSync(clean);
  installBundledSkills(root, { codexHome, projects: [clean] });
  assert.equal(removeProjectBundledSkills(clean)[0].action, "removed");
  assert.equal(existsSync(local(clean)), false);
  assert.equal(compareVersions("2.0.0", "1.9.9") > 0, true);
  console.log("bundled skill installer test passed");
} finally { rmSync(root, { recursive: true, force: true }); }
